import React, { useState, useEffect } from 'react';
import './App.css';

const API_BASE = 'http://localhost:5000/api/user';

function App() {
  // ===== STATE =====
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState(new Set());
  const [formData, setFormData] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [responseMessage, setResponseMessage] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);
  const [errorDetails, setErrorDetails] = useState('');
  const [smsConversation, setSmsConversation] = useState([]);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [serverStatus, setServerStatus] = useState('checking');
  const [activationDone, setActivationDone] = useState(false);
  const [showRegistrationComplete, setShowRegistrationComplete] = useState(false);
  const [myPhone, setMyPhone] = useState('0712345678');

  // ===== DASHBOARD STATE =====
  const [allMatches, setAllMatches] = useState([]);
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0);
  const [incomingRequests, setIncomingRequests] = useState([]);
  const [myMatches, setMyMatches] = useState([]);
  const [chatContacts, setChatContacts] = useState([]);
  const [chatMessages, setChatMessages] = useState({});
  const [newMessage, setNewMessage] = useState('');
  const [activeChatUser, setActiveChatUser] = useState(null);
  const [activeTab, setActiveTab] = useState('discover');
  const [showProfile, setShowProfile] = useState(false);
  const [showMatchDetails, setShowMatchDetails] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState(null);
  const [isSendingMessage, setIsSendingMessage] = useState(false);
  const [profileViewUser, setProfileViewUser] = useState(null);

  // ============================================
  // SAMPLE DATA
  // ============================================

  const SAMPLE_MATCHES = [
    { id: 1, phone: '0722010203', name: 'Lina Moraa', age: 29, town: 'Nairobi', county: 'Nairobi County', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', description: 'Kind-hearted and adventurous. Loves hiking and reading.' },
    { id: 2, phone: '0701223344', name: 'Dorine Gakii', age: 26, town: 'Nakuru', county: 'Nakuru County', profession: 'Teacher', education: 'Diploma', religion: 'Christian', ethnicity: 'Kamba', marital_status: 'single', description: 'Caring and dedicated. Loves children and education.' },
    { id: 3, phone: '0700112233', name: 'Aisha Bahati', age: 27, town: 'Mombasa', county: 'Mombasa County', profession: 'Accountant', education: 'Graduate', religion: 'Muslim', ethnicity: 'Swahili', marital_status: 'single', description: 'Ambitious and hardworking. I love numbers.' },
    { id: 4, phone: '0722040506', name: 'Pamela Nafula', age: 26, town: 'Kisumu', county: 'Kisumu County', profession: 'Engineer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', description: 'Tech enthusiast. Loves innovation and building solutions.' },
    { id: 5, phone: '0702556677', name: 'Maria Mwende', age: 28, town: 'Kasarani', county: 'Nairobi County', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kamba', marital_status: 'single', description: 'Diligent, loving, dedicated and will make you tick.' },
    { id: 6, phone: '0708990011', name: 'Keziah Cheptab', age: 28, town: 'Eldoret', county: 'Uasin Gishu County', profession: 'Doctor', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Kalenjin', marital_status: 'single', description: 'Passionate about healthcare and community service.' }
  ];

  const SAMPLE_REQUESTS = [
    { id: 101, phone: '0723000001', name: 'Michael Ochieng', age: 30, town: 'Nairobi', message: '💕 Shows interest in you', status: 'pending' },
    { id: 102, phone: '0723000002', name: 'David Kiprop', age: 28, town: 'Eldoret', message: '💕 Shows interest in you', status: 'pending' }
  ];

  const SAMPLE_MY_MATCHES = [
    { id: 201, phone: '0724000001', name: 'Grace Akinyi', age: 27, town: 'Kisumu', status: 'accepted' },
    { id: 202, phone: '0724000002', name: 'Peter Mwangi', age: 29, town: 'Nakuru', status: 'accepted' }
  ];

  // ============================================
  // STEPS
  // ============================================

  const STEPS = [
    {
      id: 1,
      title: 'Activate Service',
      subtitle: 'Send PENZI to activate',
      icon: '💑',
      fields: [{ key: 'penzi', label: 'Enter Activation Code', placeholder: 'Type PENZI', type: 'text' }],
      isActivation: true,
      userMessage: 'PENZI'
    },
    {
      id: 2,
      title: 'Service Registration',
      subtitle: 'Create your account',
      icon: '📝',
      fields: [
        { key: 'phone_number', label: '📱 Phone Number', placeholder: '0712345678', type: 'tel' },
        { key: 'name', label: '👤 Full Name', placeholder: 'John Doe', type: 'text' },
        { key: 'age', label: '🎂 Age', placeholder: '26', type: 'number' },
        { key: 'gender', label: '⚤ Gender', type: 'select', options: ['Male', 'Female', 'Other'] },
        { key: 'county', label: '📍 County', placeholder: 'Nakuru', type: 'text' },
        { key: 'town', label: '🏙️ Town/City', placeholder: 'Naivasha', type: 'text' }
      ],
      isRegistration: true,
      userMessage: (data) => `start#${data.name}#${data.age}#${data.gender}#${data.county}#${data.town}`,
      systemMessage: (data) => `Your profile has been created successfully ${data.name}. SMS details#levelOfEducation#profession#maritalStatus#religion#ethnicity to 22141.`
    },
    {
      id: 3,
      title: 'Details Registration',
      subtitle: 'Complete your profile',
      icon: '📋',
      fields: [
        { key: 'education_level', label: '🎓 Education Level', type: 'select', options: ['Primary', 'Secondary', 'Certificate', 'Diploma', 'Graduate', 'Post Graduate'] },
        { key: 'profession', label: '💼 Profession', placeholder: 'Accountant', type: 'text' },
        { key: 'marital_status', label: '💍 Marital Status', type: 'select', options: ['single', 'married', 'divorced', 'widowed', 'separated'] },
        { key: 'religion', label: '⛪ Religion', placeholder: 'Christian', type: 'text' },
        { key: 'ethnicity', label: '🌍 Ethnicity', placeholder: 'Kikuyu', type: 'text' }
      ],
      isDetails: true,
      userMessage: (data) => `details#${data.education_level}#${data.profession}#${data.marital_status}#${data.religion}#${data.ethnicity}`,
      systemMessage: 'This is the last stage of registration. SMS a brief description of yourself to 22141 starting with the word MYSELF.'
    },
    {
      id: 4,
      title: 'Self-Description',
      subtitle: 'Tell us about yourself',
      icon: '💭',
      fields: [{ key: 'description', label: 'Describe yourself', placeholder: 'Hardworking, honest, family-oriented...', type: 'textarea' }],
      isSelfDescription: true,
      userMessage: (data) => `MYSELF ${data.description}`,
      systemMessage: 'You are now registered for dating! To search for a MPENZI, SMS match#age#town to 22141.'
    },
    {
      id: 5,
      title: 'Matching Request',
      subtitle: 'Search for your match',
      icon: '❤️',
      fields: [
        { key: 'age_range', label: '📅 Age Range', placeholder: '26-30', type: 'text' },
        { key: 'town', label: '📍 Town/City', placeholder: 'Nairobi', type: 'text' }
      ],
      isMatching: true,
      userMessage: (data) => `match#${data.age_range}#${data.town}`,
      isFinal: true
    }
  ];

  // ============================================
  // API CALLS
  // ============================================

  const callApi = async (endpoint, method, body = null) => {
    try {
      const options = {
        method: method,
        headers: { 'Content-Type': 'application/json' }
      };
      if (body) {
        options.body = JSON.stringify(body);
      }
      const response = await fetch(`${API_BASE}${endpoint}`, options);
      return await response.json();
    } catch (error) {
      console.error('API Error:', error);
      return null;
    }
  };

  // ============================================
  // LOAD SAVED STATE
  // ============================================

  useEffect(() => {
    try {
      const saved = localStorage.getItem('penziState');
      if (saved) {
        const parsed = JSON.parse(saved);
        setCurrentStep(parsed.currentStep || 0);
        setCompletedSteps(new Set(parsed.completedSteps || []));
        setSmsConversation(parsed.smsConversation || []);
        setActivationDone(parsed.activationDone || false);
        setAllMatches(parsed.allMatches || SAMPLE_MATCHES);
        setIncomingRequests(parsed.incomingRequests || SAMPLE_REQUESTS);
        setMyMatches(parsed.myMatches || SAMPLE_MY_MATCHES);
        setChatContacts(parsed.chatContacts || []);
        setChatMessages(parsed.chatMessages || {});
        setActiveTab(parsed.activeTab || 'discover');
        setMyPhone(parsed.myPhone || '0712345678');
        if (parsed.currentUser) {
          setCurrentUser(parsed.currentUser);
          setIsLoggedIn(true);
        }
      }
    } catch (e) {
      console.warn('Could not load saved state:', e);
    }
  }, []);

  // ============================================
  // SAVE STATE
  // ============================================

  useEffect(() => {
    try {
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps),
        smsConversation,
        currentUser,
        activationDone,
        allMatches,
        incomingRequests,
        myMatches,
        chatContacts,
        chatMessages,
        activeTab,
        myPhone
      };
      localStorage.setItem('penziState', JSON.stringify(stateToSave));
    } catch (e) {
      console.warn('Could not save state:', e);
    }
  }, [currentStep, completedSteps, smsConversation, currentUser, activationDone, allMatches, incomingRequests, myMatches, chatContacts, chatMessages, activeTab, myPhone]);

  // ============================================
  // CHECK SERVER
  // ============================================

  useEffect(() => {
    checkServer();
  }, []);

  const checkServer = async () => {
    try {
      const response = await fetch(`${API_BASE}/activate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ penzi: 'penzi' })
      });
      if (response.ok || response.status === 400 || response.status === 405) {
        setServerStatus('connected');
      } else {
        setServerStatus('error');
      }
    } catch (error) {
      setServerStatus('error');
    }
  };

  // ============================================
  // HELPERS
  // ============================================

  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const addToConversation = (sender, message, isSystem = false) => {
    const entry = {
      id: Date.now(),
      sender: sender,
      message: message,
      isSystem: isSystem,
      timestamp: new Date().toLocaleTimeString()
    };
    setSmsConversation(prev => [...prev, entry]);
  };

  const addNotification = (message, type = 'success') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  const getProgress = () => {
    if (!activationDone) return 0;
    return Math.round((completedSteps.size / STEPS.length) * 100);
  };

  const goToStep = (index) => {
    if (index >= 0 && index < STEPS.length) {
      setCurrentStep(index);
    }
  };

  const buildSmsPreview = (step) => {
    if (step.id === 1) return 'PENZI';
    if (step.id === 2) {
      return `start#${formData.name || 'John Doe'}#${formData.age || '26'}#${formData.gender || 'Male'}#${formData.county || 'Nakuru'}#${formData.town || 'Naivasha'}`;
    }
    if (step.id === 3) {
      return `details#${formData.education_level || 'diploma'}#${formData.profession || 'driver'}#${formData.marital_status || 'single'}#${formData.religion || 'christian'}#${formData.ethnicity || 'mijikenda'}`;
    }
    if (step.id === 4) {
      return `MYSELF ${formData.description || 'Your description here'}`;
    }
    if (step.id === 5) {
      return `match#${formData.age_range || '26-30'}#${formData.town || 'Nairobi'}`;
    }
    return '';
  };

  // ============================================
  // LOGOUT / EXIT
  // ============================================

  const handleLogout = () => {
    localStorage.removeItem('penziState');
    setIsLoggedIn(false);
    setCurrentUser(null);
    setAllMatches([]);
    setIncomingRequests([]);
    setMyMatches([]);
    setChatContacts([]);
    setChatMessages({});
    setActiveChatUser(null);
    setSmsConversation([]);
    setActivationDone(false);
    setShowRegistrationComplete(false);
    setCurrentStep(0);
    setCompletedSteps(new Set());
    addNotification('👋 Logged out successfully!');
  };

  const goHome = () => {
    setActiveTab('discover');
    setActiveChatUser(null);
    setShowProfile(false);
    setShowMatchDetails(false);
    setSelectedMatch(null);
    addNotification('🏠 Returned to home');
  };

  // ============================================
  // DASHBOARD FUNCTIONS
  // ============================================

  const viewUserProfile = (user) => {
    setProfileViewUser(user);
    setShowProfile(true);
  };

  const viewProfile = (match) => {
    setSelectedMatch(match);
    setShowMatchDetails(true);
  };

  const handleExpressInterest = async (targetPhone) => {
    setIsLoading(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      const result = await callApi(`/${phone}/send-interest`, 'POST', { target_phone: targetPhone });
      if (result && result.success) {
        addToConversation('📱 You', `Expressing interest`, false);
        addToConversation('🤖 System', `💕 Interest sent! They will be notified.`, true);
        setAllMatches(prev => prev.filter(m => m.phone !== targetPhone));
        addNotification(`💕 Interest sent successfully!`);
      } else {
        addNotification('❌ Could not send interest.', 'error');
      }
    } catch (error) {
      addNotification('❌ Error expressing interest.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const handleAcceptRequest = async (request) => {
    setIsLoading(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      const result = await callApi(`/${phone}/respond-to-request`, 'POST', { user_phone: request.phone, action: "accept" });
      if (result && result.success) {
        const newMatch = { id: Date.now(), phone: request.phone, name: request.name, age: request.age, town: request.town, status: 'accepted' };
        setMyMatches(prev => [...prev, newMatch]);
        setIncomingRequests(prev => prev.filter(r => r.id !== request.id));
        addNotification(`✅ You accepted ${request.name}'s request!`);
        addToConversation('📱 You', `Accepted ${request.name}'s interest`, false);
        addToConversation('🤖 System', `✅ You are now matched with ${request.name}!`, true);
      } else {
        addNotification('❌ Could not accept request.', 'error');
      }
    } catch (error) {
      addNotification('❌ Error accepting request.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const handleRejectRequest = async (request) => {
    setIsLoading(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      const result = await callApi(`/${phone}/respond-to-request`, 'POST', { user_phone: request.phone, action: "reject", reason: "Not interested" });
      if (result && result.success) {
        setIncomingRequests(prev => prev.filter(r => r.id !== request.id));
        addNotification(`❌ You declined ${request.name}'s request.`);
        addToConversation('📱 You', `Declined ${request.name}'s interest`, false);
        addToConversation('🤖 System', `❌ You declined ${request.name}'s request.`, true);
      } else {
        addNotification('❌ Could not decline request.', 'error');
      }
    } catch (error) {
      addNotification('❌ Error declining request.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const loadMatches = async () => {
    setIsLoading(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      const result = await callApi(`/${phone}/matches?age_range=20-40&town=Nairobi`, 'GET');
      if (result && result.status === 'success') {
        const matchesData = result.data?.matches || result.matches || [];
        setAllMatches(matchesData);
        addNotification(`✅ Found ${matchesData.length} matches!`);
      } else {
        setAllMatches(SAMPLE_MATCHES);
      }
    } catch (error) {
      setAllMatches(SAMPLE_MATCHES);
    } finally {
      setIsLoading(false);
    }
  };

  const startChat = (match) => {
    setActiveChatUser(match);
    setActiveTab('chat');
    if (!chatContacts.some(c => c.phone === match.phone)) {
      setChatContacts(prev => [{ phone: match.phone, name: match.name, lastMessage: 'Start chatting...', time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), unread: 0 }, ...prev]);
    }
    addNotification(`💬 Chat opened with ${match.name}`);
  };

  const sendMessage = () => {
    if (!newMessage.trim() || !activeChatUser) return;
    const messageId = Date.now();
    const newMsg = { id: messageId, sender: 'You', message: newMessage, time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), isMine: true, status: 'sending' };
    setChatMessages(prev => ({ ...prev, [activeChatUser.phone]: [...(prev[activeChatUser.phone] || []), newMsg] }));
    setChatContacts(prev => prev.map(c => c.phone === activeChatUser.phone ? { ...c, lastMessage: newMessage, time: newMsg.time } : c));
    setIsSendingMessage(true);
    setNewMessage('');
    setTimeout(() => {
      setChatMessages(prev => {
        const updatedMessages = [...(prev[activeChatUser.phone] || [])];
        const index = updatedMessages.findIndex(m => m.id === messageId);
        if (index !== -1) { updatedMessages[index] = { ...updatedMessages[index], status: 'sent' }; }
        return { ...prev, [activeChatUser.phone]: updatedMessages };
      });
      setIsSendingMessage(false);
      addNotification(`📤 Message sent to ${activeChatUser.name}`);
    }, 800);
  };

  // ============================================
  // EXECUTE API (Registration Flow)
  // ============================================

  const executeApi = async () => {
    const step = STEPS[currentStep];
    setIsLoading(true);
    setResponseMessage('');
    setIsSuccess(false);
    setErrorDetails('');

    try {
      let phone = formData.phone_number || myPhone || '0712345678';

      if (step.isActivation) {
        const result = await callApi('/activate', 'POST', { penzi: formData.penzi || 'penzi' });
        if (result && result.status === 'success') {
          const welcomeMsg = result.message || 'Welcome to our dating service! To register SMS start#name#age#gender#county#town to 22141.';
          addToConversation('📱 You', 'PENZI', false);
          addToConversation('🤖 System', welcomeMsg, true);
          setActivationDone(true);
          setResponseMessage('✅ Service activated successfully!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Service activated! Proceed to registration.');
        } else {
          setResponseMessage('❌ Activation failed. Please try again.');
          setIsSuccess(false);
        }
      } else if (step.isRegistration) {
        const data = { phone_number: formData.phone_number, name: formData.name, age: formData.age, gender: formData.gender, county: formData.county, town: formData.town };
        const result = await callApi('/register', 'POST', data);
        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || step.systemMessage(formData);
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setMyPhone(formData.phone_number || '0712345678');
          setResponseMessage('✅ Registration complete!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete! Proceed to step 3.');
        } else {
          setResponseMessage('❌ Registration failed. Please try again.');
          setIsSuccess(false);
        }
      } else if (step.isDetails) {
        const data = { education_level: formData.education_level, profession: formData.profession, marital_status: formData.marital_status, religion: formData.religion, ethnicity: formData.ethnicity };
        const result = await callApi(`/${phone}/complete-profile`, 'POST', data);
        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || step.systemMessage;
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setResponseMessage('✅ Profile completed!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Profile completed! Proceed to step 4.');
        } else {
          setResponseMessage('❌ Profile completion failed. Please try again.');
          setIsSuccess(false);
        }
      } else if (step.isSelfDescription) {
        const result = await callApi(`/${phone}/self-description`, 'POST', { description: formData.description });
        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || step.systemMessage;
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setResponseMessage('✅ Self-description added!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete! Proceed to step 5.');
        } else {
          setResponseMessage('❌ Self-description failed. Please try again.');
          setIsSuccess(false);
        }
      } else if (step.isMatching) {
        const message = `match#${formData.age_range}#${formData.town}`;
        const result = await callApi('/sms', 'POST', { phone_number: phone, message: message });
        const userMsg = step.userMessage(formData);
        addToConversation('📱 You', userMsg, false);
        if (result && result.matches) {
          const matchesData = result.matches;
          setAllMatches(matchesData);
          addToConversation('🤖 System', `We have ${matchesData.length} matches who match your choice!`, true);
          matchesData.slice(0, 3).forEach(m => {
            addToConversation('🤖 System', `${m.name} aged ${m.age}, ${m.phone}.`, true);
          });
          setResponseMessage(`✅ Found ${matchesData.length} matches!`);
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          const user = { phone: formData.phone_number || phone || '0712345678', name: formData.name || 'User', age: formData.age || '26', town: formData.town || 'Nairobi' };
          setCurrentUser(user);
          setShowRegistrationComplete(true);
          setTimeout(() => {
            setIsLoggedIn(true);
            addNotification(`🎉 Welcome to PENZI! You have ${matchesData.length} matches!`);
          }, 1500);
        } else {
          setResponseMessage('❌ No matches found. Please try different criteria.');
          setIsSuccess(false);
        }
      }
    } catch (error) {
      setResponseMessage('❌ Network error. Please check your connection.');
      setIsSuccess(false);
      setErrorDetails(error.message);
      addNotification('❌ Network error', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  // ============================================
  // RENDER SMS CONVERSATION
  // ============================================

  const renderSmsConversation = () => {
    if (smsConversation.length === 0) return null;
    return (
      <div className="sms-conversation-container">
        <div className="sms-conversation-header">
          <span className="conversation-title">💬 SMS Conversation</span>
          <span className="conversation-count">{smsConversation.length} messages</span>
        </div>
        <div className="sms-conversation">
          {smsConversation.map((msg) => (
            <div key={msg.id} className={`sms-conversation-bubble ${msg.isSystem ? 'system' : 'user'}`}>
              <div className="sms-sender">{msg.sender}</div>
              <div className="sms-message">{msg.message}</div>
              <div className="sms-time">{msg.timestamp}</div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER REGISTRATION
  // ============================================

  const renderRegistration = () => {
    const step = STEPS[currentStep];
    const isFirstStep = currentStep === 0;
    const isLastStep = currentStep === STEPS.length - 1;
    const previewSms = buildSmsPreview(step);
    const isActivationStep = step.id === 1;

    return (
      <div className="registration-container">
        <div className="registration-card">
          <div className="top-actions">
            <button className="btn-top btn-home-top" onClick={() => { if (isLoggedIn) { goHome(); } else { window.location.reload(); } }}>🏠 Home</button>
            <button className="btn-top btn-exit-top" onClick={handleLogout}>🚪 Exit</button>
          </div>
          <div className="registration-header">
            <div className="registration-icon">{step.icon}</div>
            <h1>PENZI Dating</h1>
            <p className="subtitle">Find your perfect match</p>
          </div>
          <div className={`server-status ${serverStatus}`}>
            <span className="status-dot"></span>
            <span className="status-text">{serverStatus === 'connected' ? '✅ Server Connected' : serverStatus === 'checking' ? '⏳ Checking...' : '❌ Server Not Connected'}</span>
          </div>
          {activationDone && (<div className="progress-bar-container"><div className="progress-bar"><div className="progress-fill" style={{ width: `${getProgress()}%` }}></div></div><span className="progress-text">{getProgress()}% Complete • {completedSteps.size}/{STEPS.length}</span></div>)}
          {renderSmsConversation()}
          <div className="step-info-card">
            <div className="step-number">{isActivationStep ? '🔑 ENTRY POINT' : `Step ${currentStep + 1} of ${STEPS.length}`}</div>
            <h2>{step.title}</h2>
            <p>{step.subtitle}</p>
          </div>
          <form onSubmit={(e) => { e.preventDefault(); executeApi(); }} className="registration-form">
            {isActivationStep && (<div className="activation-hint"><div className="hint-bubble"><span className="hint-label">📱 To activate:</span><span className="hint-code">PENZI</span></div></div>)}
            {step.fields && step.fields.map((field) => (
              <div key={field.key} className="input-group">
                <label>{field.label}</label>
                {field.type === 'select' ? (
                  <select value={formData[field.key] || ''} onChange={(e) => handleInputChange(field.key, e.target.value)} className="input-field" required>
                    <option value="">Select {field.label}</option>
                    {field.options.map(opt => (<option key={opt} value={opt}>{opt}</option>))}
                  </select>
                ) : field.type === 'textarea' ? (
                  <textarea value={formData[field.key] || ''} onChange={(e) => handleInputChange(field.key, e.target.value)} placeholder={field.placeholder} className="textarea-field" rows={4} required />
                ) : (
                  <input type={field.type || 'text'} value={formData[field.key] || ''} onChange={(e) => handleInputChange(field.key, e.target.value)} placeholder={field.placeholder} className="input-field" required />
                )}
              </div>
            ))}
            {previewSms && (<div className="sms-preview-container"><div className="sms-preview-label">📱 Your SMS will be:</div><div className="sms-preview-content">{previewSms}</div></div>)}
            <div className="registration-actions">
              <button type="button" onClick={() => goToStep(currentStep - 1)} disabled={currentStep === 0 || isLoading || !activationDone} className="btn-secondary">⬅ Previous</button>
              <button type="submit" disabled={isLoading || serverStatus === 'error'} className={`btn-primary ${isLoading ? 'loading' : ''}`}>{isLoading ? '⏳ Sending...' : isActivationStep ? '💑 Activate' : '📤 Send'}</button>
              <button type="button" onClick={() => goToStep(currentStep + 1)} disabled={isLastStep || isLoading || !completedSteps.has(currentStep)} className="btn-secondary">Next ➡</button>
            </div>
          </form>
          {errorDetails && (<div className="error-details"><p className="error-detail-text">💡 {errorDetails}</p></div>)}
          {responseMessage && (<div className={`response-message ${isSuccess ? 'success' : 'error'}`}>{responseMessage}</div>)}
          {showRegistrationComplete && (<div className="registration-complete"><div className="complete-icon">🎉</div><h2>Registration Complete!</h2><p>Welcome to PENZI Dating, {currentUser?.name}!</p><p style={{ fontSize: '15px', color: '#6b7280' }}>You have {allMatches.length} potential matches waiting for you.</p><button className="btn-primary" style={{ marginTop: '20px', width: '100%', padding: '14px' }} onClick={() => { setIsLoggedIn(true); loadMatches(); }}>Go to Dashboard →</button></div>)}
          <div className="registration-footer"><p>🔒 Your data is safe and private</p></div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER NOTIFICATIONS
  // ============================================

  const renderNotifications = () => {
    if (notifications.length === 0) return null;
    return (
      <div className="notifications-container">
        {notifications.map((notif) => (<div key={notif.id} className={`notification ${notif.type || 'success'}`}>{notif.message}</div>))}
      </div>
    );
  };

  // ============================================
  // RENDER PROFILE MODAL
  // ============================================

  const renderProfileModal = () => {
    const user = profileViewUser || selectedMatch || currentUser;
    if (!user || !showProfile) return null;
    return (
      <div className="modal-overlay" onClick={() => { setShowProfile(false); setShowMatchDetails(false); setProfileViewUser(null); }}>
        <div className="modal-content" onClick={(e) => e.stopPropagation()}>
          <button className="modal-close" onClick={() => { setShowProfile(false); setShowMatchDetails(false); setProfileViewUser(null); }}>✕</button>
          <div className="profile-header">
            <div className="profile-avatar">{user.name?.charAt(0) || '?'}</div>
            <h2>{user.name}</h2>
            <p>{user.age || '?'} years • {user.town || 'Unknown'}</p>
          </div>
          <div className="profile-details">
            <div className="profile-item"><span className="label">📞 Phone</span><span>{user.phone}</span></div>
            <div className="profile-item"><span className="label">📍 County</span><span>{user.county || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">💼 Profession</span><span>{user.profession || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🎓 Education</span><span>{user.education || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">💍 Marital Status</span><span>{user.marital_status || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🙏 Religion</span><span>{user.religion || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🌍 Ethnicity</span><span>{user.ethnicity || 'Not specified'}</span></div>
            {user.description && (<div className="profile-item full-width"><span className="label">💭 About Me</span><span>{user.description}</span></div>)}
          </div>
          <div className="modal-actions">
            <button className="btn-secondary" onClick={() => { setShowProfile(false); setShowMatchDetails(false); setProfileViewUser(null); }}>Close</button>
            {selectedMatch && (<button className="btn-primary" onClick={() => { handleExpressInterest(selectedMatch.phone); setShowMatchDetails(false); setSelectedMatch(null); }}>💕 Express Interest</button>)}
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER DASHBOARD
  // ============================================

  const renderDashboard = () => {
    const currentMatch = allMatches[currentMatchIndex] || allMatches[0];
    const hasMatches = allMatches.length > 0;
    const hasRequests = incomingRequests.length > 0;
    const hasMyMatches = myMatches.length > 0;
    const hasChatContacts = chatContacts.length > 0;
    const currentChatMessages = activeChatUser ? (chatMessages[activeChatUser.phone] || []) : [];

    return (
      <div className="dashboard-container">
        <header className="dashboard-header">
          <div className="header-left">
            <button className="btn-home" onClick={goHome} title="Home">🏠</button>
            <h1>💑 PENZI</h1>
            <span className="live-badge">❤️ Live</span>
          </div>
          <div className="header-right">
            <span className="user-greeting">👋 {currentUser?.name || 'User'}</span>
            <button className="profile-btn" onClick={() => { setProfileViewUser(currentUser); setShowProfile(true); }}>👤</button>
            <button className="btn-exit" onClick={handleLogout} title="Logout">🚪</button>
          </div>
        </header>
        <nav className="dashboard-nav">
          <button className={`nav-item ${activeTab === 'discover' ? 'active' : ''}`} onClick={() => setActiveTab('discover')}>🔍 Discover <span className="nav-badge">{allMatches.length}</span></button>
          <button className={`nav-item ${activeTab === 'matches' ? 'active' : ''}`} onClick={() => setActiveTab('matches')}>💕 Matches <span className="nav-badge">{myMatches.length}</span></button>
          <button className={`nav-item ${activeTab === 'requests' ? 'active' : ''}`} onClick={() => setActiveTab('requests')}>📬 Requests {incomingRequests.length > 0 && <span className="nav-badge red">{incomingRequests.length}</span>}</button>
          <button className={`nav-item ${activeTab === 'chat' ? 'active' : ''}`} onClick={() => setActiveTab('chat')}>💬 Chat {hasChatContacts && <span className="nav-badge">{chatContacts.length}</span>}</button>
        </nav>
        <main className="dashboard-content">
          {activeTab === 'discover' && (
            <div className="discover-container">
              {hasMatches ? (
                <div className="match-card">
                  <div className="match-card-header">
                    <div className="match-avatar" onClick={() => viewProfile(currentMatch)}>{currentMatch?.name?.charAt(0) || '?'}</div>
                    <div className="match-info"><h3>{currentMatch?.name || 'Unknown'}</h3><p>{currentMatch?.age || '?'} years • {currentMatch?.town || 'Unknown'}</p></div>
                  </div>
                  <div className="match-details">
                    <div className="detail-item"><span className="detail-label">💼 Profession</span><span className="detail-value">{currentMatch?.profession || 'Not specified'}</span></div>
                    <div className="detail-item"><span className="detail-label">🎓 Education</span><span className="detail-value">{currentMatch?.education || 'Not specified'}</span></div>
                    <div className="detail-item"><span className="detail-label">🙏 Religion</span><span className="detail-value">{currentMatch?.religion || 'Not specified'}</span></div>
                    <div className="detail-item"><span className="detail-label">🌍 Ethnicity</span><span className="detail-value">{currentMatch?.ethnicity || 'Not specified'}</span></div>
                    {currentMatch?.description && (<div className="detail-item full-width"><span className="detail-label">💭 About Me</span><span className="detail-value description">{currentMatch.description}</span></div>)}
                  </div>
                  <div className="match-actions">
                    <button className="btn-secondary" onClick={() => viewProfile(currentMatch)}>👤 View Profile</button>
                    <button className="btn-primary" onClick={() => handleExpressInterest(currentMatch.phone)} disabled={isLoading}>{isLoading ? '⏳' : '💕 I\'m Interested'}</button>
                  </div>
                  <div className="match-navigation">
                    <button className="nav-btn" onClick={() => setCurrentMatchIndex(Math.max(0, currentMatchIndex - 1))} disabled={currentMatchIndex === 0}>⬅ Previous</button>
                    <span className="match-counter">{currentMatchIndex + 1} of {allMatches.length}</span>
                    <button className="nav-btn" onClick={() => setCurrentMatchIndex(Math.min(allMatches.length - 1, currentMatchIndex + 1))} disabled={currentMatchIndex === allMatches.length - 1}>Next ➡</button>
                  </div>
                </div>
              ) : (
                <div className="empty-state">
                  <div className="empty-icon">🔍</div>
                  <h2>No Matches Found</h2>
                  <p>Try different search criteria or check back later</p>
                  <button className="btn-primary" onClick={loadMatches}>🔄 Refresh Matches</button>
                </div>
              )}
            </div>
          )}
          {activeTab === 'matches' && (
            <div className="matches-container">
              {hasMyMatches ? (
                <div className="matches-grid">
                  {myMatches.map((match) => (
                    <div key={match.id} className="match-item">
                      <div className="match-avatar" onClick={() => viewUserProfile(match)}>{match.name?.charAt(0) || '?'}</div>
                      <div className="match-info">
                        <h4 onClick={() => viewUserProfile(match)}>{match.name}</h4>
                        <p>{match.age} years • {match.town}</p>
                        <span className="match-status">✅ Accepted</span>
                      </div>
                      <button className="btn-chat" onClick={() => startChat(match)}>💬</button>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="empty-state">
                  <div className="empty-icon">💕</div>
                  <h2>No Matches Yet</h2>
                  <p>Start discovering and accepting requests</p>
                  <div className="empty-actions">
                    <button className="btn-primary" onClick={() => setActiveTab('discover')}>🔍 Discover People</button>
                    <button className="btn-secondary" onClick={() => setActiveTab('requests')}>📬 View Requests</button>
                  </div>
                </div>
              )}
            </div>
          )}
          {activeTab === 'requests' && (
            <div className="requests-container">
              {hasRequests ? (
                <div className="requests-list">
                  {incomingRequests.map((request) => (
                    <div key={request.id} className="request-item">
                      <div className="request-info">
                        <div className="request-avatar" onClick={() => viewUserProfile(request)}>{request.name?.charAt(0) || '?'}</div>
                        <div>
                          <h4 onClick={() => viewUserProfile(request)}>{request.name}</h4>
                          <p>{request.age} years • {request.town}</p>
                          <p className="request-message">💕 {request.message}</p>
                        </div>
                      </div>
                      <div className="request-actions">
                        <button className="btn-accept" onClick={() => handleAcceptRequest(request)} disabled={isLoading}>{isLoading ? '⏳' : '✅ Accept'}</button>
                        <button className="btn-decline" onClick={() => handleRejectRequest(request)} disabled={isLoading}>{isLoading ? '⏳' : '❌ Decline'}</button>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="empty-state">
                  <div className="empty-icon">📬</div>
                  <h2>No Requests</h2>
                  <p>When someone shows interest, it will appear here</p>
                  <button className="btn-primary" onClick={() => setActiveTab('discover')}>🔍 Discover People</button>
                </div>
              )}
            </div>
          )}
          {activeTab === 'chat' && (
            <div className="chat-container">
              {activeChatUser ? (
                <div className="chat-view">
                  <div className="chat-header">
                    <div className="chat-header-info">
                      <button className="btn-back-chat" onClick={() => setActiveChatUser(null)}>←</button>
                      <div className="chat-header-avatar" onClick={() => viewUserProfile(activeChatUser)}>{activeChatUser.name?.charAt(0) || '?'}</div>
                      <div className="chat-header-name"><h4 onClick={() => viewUserProfile(activeChatUser)}>{activeChatUser.name}</h4><span className="chat-header-status">Online</span></div>
                    </div>
                    <button className="btn-close-chat" onClick={() => setActiveChatUser(null)}>✕</button>
                  </div>
                  <div className="chat-messages">
                    {currentChatMessages.length === 0 ? (
                      <div className="empty-state"><div className="empty-icon">💬</div><h3>No Messages</h3><p>Start a conversation with {activeChatUser.name}</p></div>
                    ) : (
                      currentChatMessages.map((msg) => (
                        <div key={msg.id} className={`message ${msg.isMine ? 'sent' : 'received'}`}>
                          <p>{msg.message}</p>
                          <span className="message-time">{msg.time}</span>
                          {msg.isMine && msg.status === 'sending' && <span className="message-status">⏳ Sending...</span>}
                          {msg.isMine && msg.status === 'sent' && <span className="message-status">✓ Sent</span>}
                        </div>
                      ))
                    )}
                  </div>
                  <div className="chat-input">
                    <input type="text" value={newMessage} onChange={(e) => setNewMessage(e.target.value)} placeholder={`Message ${activeChatUser.name}...`} onKeyPress={(e) => { if (e.key === 'Enter') sendMessage(); }} disabled={isSendingMessage} />
                    <button className="btn-send" onClick={sendMessage} disabled={!newMessage.trim() || isSendingMessage}>{isSendingMessage ? '⏳' : 'Send'}</button>
                  </div>
                </div>
              ) : (
                <div className="chat-contact-list">
                  <div className="chat-list-header"><h3>💬 Chats</h3><span className="chat-list-count">{chatContacts.length} contacts</span></div>
                  {hasChatContacts ? (
                    <div className="chat-contacts">
                      {chatContacts.map((contact) => (
                        <div key={contact.phone} className="chat-contact-item" onClick={() => { const match = myMatches.find(m => m.phone === contact.phone); if (match) { setActiveChatUser(match); setChatContacts(prev => prev.map(c => c.phone === contact.phone ? { ...c, unread: 0 } : c)); } }}>
                          <div className="contact-avatar">{contact.name?.charAt(0) || '?'}</div>
                          <div className="contact-info"><div className="contact-name">{contact.name}</div><div className="contact-last-message">{contact.lastMessage || 'Start chatting...'}</div></div>
                          <div className="contact-meta"><div className="contact-time">{contact.time}</div>{contact.unread > 0 && <div className="contact-unread">{contact.unread}</div>}</div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className="empty-state"><div className="empty-icon">💬</div><h3>No Conversations</h3><p>Start chatting with your matches</p><button className="btn-primary" onClick={() => setActiveTab('matches')}>💕 View Matches</button></div>
                  )}
                </div>
              )}
            </div>
          )}
        </main>
        {showProfile && renderProfileModal()}
      </div>
    );
  };

  // ============================================
  // MAIN RETURN
  // ============================================

  return (
    <div className="app">
      {renderNotifications()}
      {isLoggedIn ? renderDashboard() : renderRegistration()}
    </div>
  );
}

export default App;
